import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges } from '@angular/core';
import { DocInfo, linkExplorer, linkExplorerList, linkExplorerType, toolEvents } from '../../interfaces/pdf.interface';
import { PdfDataService } from '../../service/pdf-data.service';
import { MatSelectModule } from '@angular/material/select';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { FormsModule } from '@angular/forms';
import { SourceCardComponent } from '../../../shared/components/source-card/source-card.component';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { ErrorHandlerUtil } from '../../../userpanel/utility/error-handler.util';

@Component({
  selector: 'link-explorer',
  standalone: true,
  imports: [MatSelectModule, IconComponent, ButtonComponent, FormsModule, SourceCardComponent, TranslateModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './linkexplorer-tools.component.html',
  styleUrl: './linkexplorer-tools.component.scss'
})
export class LinkexplorerToolsComponent implements OnInit, OnChanges {

  @Input() docInfo: DocInfo | null = null;
  @Input() linkExplorerMode: linkExplorer | null = null;
  @Input() linkExplorerType: linkExplorerType = 'F';
  linkedList: linkExplorerList[] = [];
  isLoaded = false;
  selectedLink: linkExplorerList | null = null;

  @Output() onEvent = new EventEmitter<toolEvents>();

  constructor(private readonly pdfDataService: PdfDataService, private readonly cdr: ChangeDetectorRef, private readonly translate: TranslateService) {}

  ngOnInit(): void {
    void this.loadLinks();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['linkExplorerType'] && !changes['linkExplorerType'].firstChange) {
      this.isLoaded = false;
      void this.loadLinks();
    }
  }

  linkChange(type: linkExplorerType): void {
    this.selectedLink = null;
    this.linkExplorerType = type;
    this.linkedList = [];
    this.isLoaded = false;
    this.onEvent.emit({ event: 'LINK-EXPLORER-TYPE', data: this.linkExplorerType });
    // this.ngOnInit();
  }


  ChangeFile(val: number): void {
    const ind = this.selectedLink ? this.linkedList.findIndex(x => x === this.selectedLink) : -1;
    if (this.linkedList[ind + val]) {
      this.selectedLink = this.linkedList[ind + val];
      this.changeDoc(this.selectedLink);
      this.cdr.detectChanges();
    }
  }


  changeDoc(e: linkExplorerList) {
    this.onEvent.emit({ event: 'LINK-EXPLORER-CHANGEDOC', data: { file: e, mode: this.linkExplorerMode === 'I' ? 'O' : 'I', type: this.linkExplorerType } });
  }

  getPlaceholder(): string {
    if (this.linkExplorerMode == 'I') {
      if (this.linkExplorerType == 'F') return this.translate.instant('LINKS.EXPLORER.SELECT_INCOMING_FACTLINK');
      return this.translate.instant('LINKS.EXPLORER.SELECT_INCOMING_DOCLINK');
    }
    else {
      if (this.linkExplorerType == 'F') return this.translate.instant('LINKS.EXPLORER.SELECT_OUTGOING_FACTLINK');
      return this.translate.instant('LINKS.EXPLORER.SELECT_OUTGOING_DOCLINK');
    }
  }

  private async loadLinks(): Promise<void> {
    this.linkedList = [];
    if (!this.docInfo || !this.docInfo.nBundledetailid || !this.linkExplorerMode) {
      this.cdr.detectChanges();
      return;
    }

    try {
      const res = await this.pdfDataService.getLinks(this.docInfo.nBundledetailid, `${this.linkExplorerMode}${this.linkExplorerType}`);
      if (Array.isArray(res) && res.length > 0) {
        this.linkedList = res;
      }
    } catch (error: unknown) {
      const errMsg = ErrorHandlerUtil.getErrorMessage(error);
      throw new Error(errMsg);
    } finally {
      this.cdr.detectChanges();
    }
  }

}
